		}
		TraceMemoryOperations ops = getMemoryOps(true);
		if (ops == null) {
			throw new AssertionError("Cannot get memory operations for writing. " +
				"This usually indicates a schema issue.");
		}
		ops.setState(snap, toOverlay(hostRange), state);
